{"command":"cat > Cargo.toml <<'EOF'
[package]
name = "b3sum"
version = "1.8.4"
edition = "2021"

[dependencies]
clap = { version = "4.6", default-features = false, features = ["std","help","usage","error-context","suggestions"] }

[[bin]]
name = "b3sum"
path = "src/main.rs"
EOF
cat Cargo.toml
mkdir -p src
cat > src/main.rs <<'RS'
use clap::{Arg, ArgAction, Command, value_parser};
use std::io::{self, Read, Write};
use std::fs::File;
use std::path::Path;

const IV: [u32; 8] = [
    0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A,
    0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19,
];
const MSG_PERMUTATION: [usize; 16] = [2,6,3,10,7,0,4,13,1,11,12,5,9,14,15,8];
const CHUNK_START: u32 = 1;
const CHUNK_END: u32 = 2;
const PARENT: u32 = 4;
const ROOT: u32 = 8;
const KEYED_HASH: u32 = 16;
const DERIVE_KEY_CONTEXT: u32 = 32;
const DERIVE_KEY_MATERIAL: u32 = 64;
const BLOCK_LEN: u32 = 64;
const CHUNK_LEN: usize = 1024;

fn rotr(x: u32, n: u32) -> u32 {
    (x >> n) | (x << (32 - n))
}
fn g(state: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize, mx: u32, my: u32) {
    state[a] = state[a].wrapping_add(state[b]).wrapping_add(mx);
    state[d] = rotr(state[d] ^ state[a], 16);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = rotr(state[b] ^ state[c], 12);
    state[a] = state[a].wrapping_add(state[b]).wrapping_add(my);
    state[d] = rotr(state[d] ^ state[a], 8);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = rotr(state[b] ^ state[c], 7);
}
fn round_fn(state: &mut [u32; 16], m: &[u32; 16]) {
    g(state, 0,4,8,12, m[0], m[1]);
    g(state, 1,5,9,13, m[2], m[3]);
    g(state, 2,6,10,14, m[4], m[5]);
    g(state, 3,7,11,15, m[6], m[7]);
    g(state, 0,5,10,15, m[8], m[9]);
    g(state, 1,6,11,12, m[10], m[11]);
    g(state, 2,7,8,13, m[12], m[13]);
    g(state, 3,4,9,14, m[14], m[15]);
}
fn compress(chaining_value: &[u32; 8], block_words: &[u32; 16], counter: u64, block_len: u32, flags: u32) -> [u32; 16] {
    let mut state = [0u32; 16];
    state[0..8].copy_from_slice(chaining_value);
    state[8..12].copy_from_slice(&IV[0..4]);
    state[12] = (counter & 0xffffffff) as u32;
    state[13] = ((counter >> 32) & 0xffffffff) as u32;
    state[14] = block_len;
    state[15] = flags;
    let mut m = *block_words;
    for _ in 0..7 {
        round_fn(&mut state, &m);
        let mut permuted = [0u32; 16];
        for i in 0..16 {
            permuted[i] = m[MSG_PERMUTATION[i]];
        }
        m = permuted;
    }
    for i in 0..8 {
        state[i] ^= state[i+8];
        state[i+8] ^= chaining_value[i];
    }
    state
}
fn words_from_block(block: &[u8]) -> [u32; 16] {
    let mut words = [0u32; 16];
    for i in 0..16 {
        words[i] = u32::from_le_bytes([block[i*4], block[i*4+1], block[i*4+2], block[i*4+3]]);
    }
    words
}
fn words_from_block_safe(block: &[u8]) -> [u32; 16] {
    let mut buf = [0u8; 64];
    let len = std::cmp::min(block.len(), 64);
    buf[..len].copy_from_slice(&block[..len]);
    words_from_block(&buf)
}
fn le_bytes_from_words(words: &[u32]) -> Vec<u8> {
    let mut out = Vec::with_capacity(words.len()*4);
    for w in words {
        out.extend_from_slice(&w.to_le_bytes());
    }
    out
}
fn key_words_from_bytes(key: &[u8]) -> [u32; 8] {
    let mut out = [0u32; 8];
    for i in 0..8 {
        out[i] = u32::from_le_bytes([key[i*4], key[i*4+1], key[i*4+2], key[i*4+3]]);
    }
    out
}
fn hash_general(data: &[u8], base_flags: u32, key_words: &[u32; 8], seek: u64, length: u64) -> Vec<u8> {
    let length = length as usize;
    let seek = seek as usize;
    if data.is_empty() {
        // single empty chunk
        return hash_single_chunk(b"", base_flags, key_words, seek, length);
    }
    let chunks: Vec<&[u8]> = data.chunks(CHUNK_LEN).collect();
    if chunks.len() == 1 {
        return hash_single_chunk(chunks[0], base_flags, key_words, seek, length);
    }
    // multi chunk
    let mut chunk_cvs: Vec<[u32; 8]> = Vec::new();
    for (idx, chunk) in chunks.iter().enumerate() {
        let mut cv = *key_words;
        let num_blocks = (chunk.len() + 63) / 64;
        let n = if num_blocks==0 {1} else {num_blocks};
        for b_idx in 0..n {
            let start = b_idx*64;
            let end = std::cmp::min(start+64, chunk.len());
            let block_len = if b_idx == n-1 { (chunk.len() - start) as u32 } else { 64 };
            // need to create padded block for words
            let mut block_buf = [0u8; 64];
            if b_idx == n-1 {
                let slice = &chunk[start..end];
                block_buf[..slice.len()].copy_from_slice(slice);
            } else {
                block_buf.copy_from_slice(&chunk[start..start+64]);
            }
            let block_words = words_from_block(&block_buf);
            let mut flags = base_flags;
            if b_idx==0 { flags |= CHUNK_START; }
            if b_idx==n-1 { flags |= CHUNK_END; }
            let state = compress(&cv, &block_words, idx as u64, block_len, flags);
            let mut new_cv = [0u32;8];
            new_cv.copy_from_slice(&state[0..8]);
            cv = new_cv;
        }
        chunk_cvs.push(cv);
    }
    // parent tree
    let mut stack = chunk_cvs;
    while stack.len() > 1 {
        if stack.len() == 2 {
            let left = stack[0];
            let right = stack[1];
            let flags = base_flags | PARENT | ROOT;
            let mut block_words = [0u32;16];
            block_words[0..8].copy_from_slice(&left);
            block_words[8..16].copy_from_slice(&right);
            let mut out = Vec::new();
            let needed = seek+length;
            let mut counter: u64 = 0;
            while out.len() < needed {
                let state = compress(key_words, &block_words, counter, BLOCK_LEN, flags);
                out.extend_from_slice(&le_bytes_from_words(&state));
                counter+=1;
            }
            return out[seek..seek+length].to_vec();
        } else {
            let mut new_stack: Vec<[u32;8]> = Vec::new();
            let mut i=0;
            while i < stack.len() {
                if i+1 < stack.len() {
                    let left = stack[i];
                    let right = stack[i+1];
                    let flags = base_flags | PARENT;
                    let mut block_words = [0u32;16];
                    block_words[0..8].copy_from_slice(&left);
                    block_words[8..16].copy_from_slice(&right);
                    let state = compress(key_words, &block_words, 0, BLOCK_LEN, flags);
                    let mut cv = [0u32;8];
                    cv.copy_from_slice(&state[0..8]);
                    new_stack.push(cv);
                    i+=2;
                } else {
                    new_stack.push(stack[i]);
                    i+=1;
                }
            }
            stack = new_stack;
        }
    }
    Vec::new()
}
fn hash_single_chunk(chunk: &[u8], base_flags: u32, key_words: &[u32;8], seek: usize, length: usize) -> Vec<u8> {
    let num_blocks = if chunk.is_empty() {1} else {(chunk.len()+63)/64};
    let mut cv = *key_words;
    for b_idx in 0..num_blocks-1 {
        let start = b_idx*64;
        let block = &chunk[start..start+64];
        let block_words = words_from_block(block);
        let mut flags = base_flags;
        if b_idx==0 { flags |= CHUNK_START; }
        let state = compress(&cv, &block_words, 0, 64, flags);
        let mut new_cv=[0u32;8];
        new_cv.copy_from_slice(&state[0..8]);
        cv = new_cv;
    }
    let last_start = (num_blocks-1)*64;
    let last_slice = if chunk.is_empty() {&[][..]} else {&chunk[last_start..]};
    let last_len = last_slice.len() as u32;
    let mut last_buf = [0u8;64];
    last_buf[..last_slice.len()].copy_from_slice(last_slice);
    let last_words = words_from_block(&last_buf);
    let mut flags_last = base_flags;
    if num_blocks==1 { flags_last |= CHUNK_START; }
    flags_last |= CHUNK_END|ROOT;
    let mut out = Vec::new();
    let needed = seek+length;
    let mut counter: u64 = 0;
    while out.len() < needed {
        let state = compress(&cv, &last_words, counter, last_len, flags_last);
        out.extend_from_slice(&le_bytes_from_words(&state));
        counter+=1;
    }
    out[seek..seek+length].to_vec()
}
fn hash_derive(data: &[u8], context: &str, seek: u64, length: u64) -> Vec<u8> {
    let ctx_bytes = context.as_bytes();
    let ctx_key = hash_general(ctx_bytes, DERIVE_KEY_CONTEXT, &IV, 0, 32);
    let kw = key_words_from_bytes(&ctx_key);
    hash_general(data, DERIVE_KEY_MATERIAL, &kw, seek, length)
}

// escape helpers
fn needs_escape(s: &str) -> bool {
    s.contains('\\') || s.contains('\n') || s.contains('\r')
}
fn escape_filename(s: &str) -> String {
    if needs_escape(s) {
        let mut esc = String::new();
        for c in s.chars() {
            match c {
                '\\' => esc.push_str("\\\\"),
                '\n' => esc.push_str("\\n"),
                '\r' => esc.push_str("\\r"),
                _ => esc.push(c),
            }
        }
        format!("\\{}", esc)
    } else {
        s.to_string()
    }
}
fn unescape_filename(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c=='\\' {
            if let Some(n) = chars.next() {
                match n {
                    '\\' => out.push('\\'),
                    'n' => out.push('\n'),
                    'r' => out.push('\r'),
                    _ => { out.push('\\'); out.push(n); }
                }
            } else {
                out.push('\\');
            }
        } else {
            out.push(c);
        }
    }
    out
}
fn hex_encode(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len()*2);
    for b in bytes {
        s.push_str(&format!("{:02x}", b));
    }
    s
}

fn build_cmd() -> Command {
    Command::new("b3sum")
        .version("1.8.4")
        .about("")
        .arg(Arg::new("FILE")
            .value_name("FILE")
            .help("Files to hash, or checkfiles to check")
            .long_help("Files to hash, or checkfiles to check\n\nWhen no file is given, or when - is given, read standard input.")
            .num_args(0..)
        )
        .arg(Arg::new("keyed")
            .long("keyed")
            .help("Use the keyed mode, reading the 32-byte key from stdin")
            .action(ArgAction::SetTrue)
            .conflicts_with("derive-key")
            .conflicts_with("check")
        )
        .arg(Arg::new("derive-key")
            .long("derive-key")
            .value_name("CONTEXT")
            .help("Use the key derivation mode, with the given context string")
            .long_help("Use the key derivation mode, with the given context string\n\nCannot be used with --keyed.")
            .conflicts_with("keyed")
            .conflicts_with("check")
        )
        .arg(Arg::new("length")
            .short('l')
            .long("length")
            .value_name("LEN")
            .help("The number of output bytes, before hex encoding")
            .long_help("The number of output bytes, before hex encoding\n\n[default: 32]")
            .value_parser(value_parser!(u64))
            .default_value("32")
            .conflicts_with("check")
        )
        .arg(Arg::new("seek")
            .long("seek")
            .value_name("SEEK")
            .help("The starting output byte offset, before hex encoding")
            .long_help("The starting output byte offset, before hex encoding\n\n[default: 0]")
            .value_parser(value_parser!(u64))
            .default_value("0")
        )
        .arg(Arg::new("num-threads")
            .long("num-threads")
            .value_name("NUM")
            .help("The maximum number of threads to use")
            .long_help("The maximum number of threads to use\n\nBy default, this is the number of logical cores. If this flag is omitted, or if its value\nis 0, RAYON_NUM_THREADS is also respected.")
            .value_parser(value_parser!(u64))
        )
        .arg(Arg::new("no-mmap")
            .long("no-mmap")
            .help("Disable memory mapping")
            .long_help("Disable memory mapping\n\nCurrently this also disables multithreading.")
            .action(ArgAction::SetTrue)
        )
        .arg(Arg::new("no-names")
            .long("no-names")
            .help("Omit filenames in the output")
            .action(ArgAction::SetTrue)
            .conflicts_with("check")
        )
        .arg(Arg::new("raw")
            .long("raw")
            .help("Write raw output bytes to stdout, rather than hex")
            .long_help("Write raw output bytes to stdout, rather than hex\n\n--no-names is implied. In this case, only a single input is allowed.")
            .action(ArgAction::SetTrue)
            .conflicts_with("check")
        )
        .arg(Arg::new("tag")
            .long("tag")
            .help("Output BSD-style checksums: BLAKE3 ([FILE]) = [HASH]")
            .action(ArgAction::SetTrue)
            .conflicts_with("check")
        )
        .arg(Arg::new("check")
            .short('c')
            .long("check")
            .help("Read BLAKE3 sums from the [FILE]s and check them")
            .action(ArgAction::SetTrue)
            .conflicts_with("keyed")
            .conflicts_with("derive-key")
            .conflicts_with("length")
            .conflicts_with("raw")
            .conflicts_with("tag")
            .conflicts_with("no-names")
        )
        .arg(Arg::new("quiet")
            .long("quiet")
            .help("Skip printing OK for each checked file")
            .long_help("Skip printing OK for each checked file\n\nMust be used with --check.")
            .action(ArgAction::SetTrue)
            .requires("check")
        )
}

fn main() {
    let cmd = build_cmd();
    let matches = match cmd.try_get_matches() {
        Ok(m) => m,
        Err(e) => e.exit(),
    };

    let check = matches.get_flag("check");
    let keyed = matches.get_flag("keyed");
    let derive_key: Option<String> = matches.get_one::<String>("derive-key").cloned();
    let length = *matches.get_one::<u64>("length").unwrap();
    let seek = *matches.get_one::<u64>("seek").unwrap();
    let raw = matches.get_flag("raw");
    let tag = matches.get_flag("tag");
    let no_names = matches.get_flag("no-names");
    let quiet = matches.get_flag("quiet");
    // let no_mmap = matches.get_flag("no-mmap");
    // let num_threads = matches.get_one::<u64>("num-threads").copied();

    let files: Vec<String> = matches.get_many::<String>("FILE").map(|v| v.cloned().collect()).unwrap_or_default();

    // raw single file check (custom)
    if raw && files.len() > 1 {
        eprintln!("Error: Only one filename can be provided when using --raw");
        std::process::exit(1);
    }
    // keyed requires at least one FILE
    if keyed && files.is_empty() {
        // emulate clap error
        let mut cmd2 = build_cmd();
        let err = cmd2.error(clap::error::ErrorKind::MissingRequiredArgument, "the following required arguments were not provided:\n  <FILE>...");
        err.exit();
    }

    if check {
        // check mode: seek allowed, length already prevented via conflict, but also need to handle seek value
        run_check(files, quiet, seek);
        return;
    }

    // hashing mode
    // handle keyed / derive
    let mut base_flags = 0u32;
    let mut key_words: [u32; 8] = IV;

    if keyed {
        // read 32 bytes from stdin
        let mut stdin = io::stdin();
        let mut buf = Vec::new();
        // read all stdin for key
        let mut all = Vec::new();
        let mut handle = stdin.lock();
        handle.read_to_end(&mut all).unwrap();
        if all.len() < 32 {
            eprintln!("Error: expected 32 key bytes from stdin, found {}", all.len());
            std::process::exit(1);
        } else if all.len() > 32 {
            eprintln!("Error: read more than 32 key bytes from stdin");
            std::process::exit(1);
        }
        key_words = key_words_from_bytes(&all);
        base_flags = KEYED_HASH;
        // special handling for file "-": cannot open '-' in keyed mode
        for f in &files {
            if f == "-" {
                eprintln!("b3sum: -: Cannot open `-` in keyed mode");
                std::process::exit(1);
            }
        }
        // now hash files
        run_hash(files, base_flags, key_words, seek, length, raw, tag, no_names);
    } else if let Some(ctx) = derive_key {
        // derive mode
        // key_words derived from context
        // data from files or stdin
        // base_flags will be DERIVE_KEY_MATERIAL but need ctx key
        // we will compute inside run_hash_derive
        run_hash_derive(files, ctx, seek, length, raw, tag, no_names);
    } else {
        base_flags = 0;
        key_words = IV;
        run_hash(files, base_flags, key_words, seek, length, raw, tag, no_names);
    }
}

fn run_hash(files: Vec<String>, base_flags: u32, key_words: [u32;8], seek:u64, length:u64, raw:bool, tag:bool, no_names:bool) {
    let mut exit_code = 0;
    let stdout = io::stdout();
    let mut stdout_lock = stdout.lock();
    let stderr = io::stderr();
    let mut stderr_lock = stderr.lock();

    // helper to hash data
    let mut stdin_cache: Option<Vec<u8>> = None;
    let mut stdin_pos = 0; // not needed for hashing mode raw single? We'll just read once
    // For hashing, we need to handle multiple "-" reading sequentially: first gets all, subsequent empty
    // We'll read stdin once on first demand
    let mut stdin_data: Option<Vec<u8>> = None;
    let mut stdin_consumed = false;

    let get_stdin = |stdin_data: &mut Option<Vec<u8>>, consumed: &mut bool| -> Vec<u8> {
        if *consumed {
            return Vec::new();
        }
        if stdin_data.is_none() {
            let mut buf = Vec::new();
            io::stdin().lock().read_to_end(&mut buf).unwrap();
            *stdin_data = Some(buf);
        }
        *consumed = true;
        stdin_data.as_ref().unwrap().clone()
    };

    if files.is_empty() {
        // read stdin
        let mut data = Vec::new();
        io::stdin().lock().read_to_end(&mut data).unwrap();
        let out_bytes = hash_general(&data, base_flags, &key_words, seek, length);
        if raw {
            stdout_lock.write_all(&out_bytes).unwrap();
        } else if no_names || raw {
            let hex = hex_encode(&out_bytes);
            writeln!(stdout_lock, "{}", hex).unwrap();
        } else if tag {
            let hex = hex_encode(&out_bytes);
            writeln!(stdout_lock, "BLAKE3 (-) = {}", hex).unwrap();
        } else {
            let hex = hex_encode(&out_bytes);
            writeln!(stdout_lock, "{}  -", hex).unwrap();
        }
        return;
    }

    for fname in files {
        let display_name = fname.clone();
        let is_stdin = fname == "-";
        let data_res: Result<Vec<u8>, io::Error> = if is_stdin {
            // read stdin sequentially
            if stdin_consumed {
                Ok(Vec::new())
            } else {
                if stdin_data.is_none() {
                    let mut buf = Vec::new();
                    io::stdin().lock().read_to_end(&mut buf).unwrap();
                    stdin_data = Some(buf);
                }
                stdin_consumed = true;
                Ok(stdin_data.as_ref().unwrap().clone())
            }
        } else {
            // check if path is directory, permission etc.
            let path = Path::new(&fname);
            match File::open(path) {
                Ok(mut f) => {
                    // check if directory (on linux, open directory succeeds? but read will fail? Let's use metadata)
                    match std::fs::metadata(path) {
                        Ok(meta) if meta.is_dir() => {
                            Err(io::Error::new(io::ErrorKind::IsADirectory, "Is a directory"))
                        },
                        Ok(_) => {
                            let mut buf = Vec::new();
                            match f.read_to_end(&mut buf) {
                                Ok(_) => Ok(buf),
                                Err(e) => Err(e),
                            }
                        },
                        Err(e) => Err(e),
                    }
                },
                Err(e) => Err(e),
            }
        };

        match data_res {
            Ok(data) => {
                let out_bytes = hash_general(&data, base_flags, &key_words, seek, length);
                if raw {
                    // raw already enforced single file, so just write
                    stdout_lock.write_all(&out_bytes).unwrap();
                } else if no_names {
                    let hex = hex_encode(&out_bytes);
                    writeln!(stdout_lock, "{}", hex).unwrap();
                } else if tag {
                    let hex = hex_encode(&out_bytes);
                    let esc = if needs_escape(&display_name) {
                        // for tag, need to escape and prefix
                        let escaped = display_name.replace("\\", "\\\\").replace("\n","\\n").replace("\r","\\r");
                        format!("\\BLAKE3 ({}) = {}", escaped, hex)
                    } else {
                        format!("BLAKE3 ({}) = {}", display_name, hex)
                    };
                    writeln!(stdout_lock, "{}", esc).unwrap();
                } else {
                    let hex = hex_encode(&out_bytes);
                    let out_line = if needs_escape(&display_name) {
                        let escaped = display_name.replace("\\", "\\\\").replace("\n","\\n").replace("\r","\\r");
                        format!("\\{}  {}", hex, escaped)
                    } else {
                        format!("{}  {}", hex, display_name)
                    };
                    writeln!(stdout_lock, "{}", out_line).unwrap();
                }
            },
            Err(e) => {
                let kind = e.kind();
                let code = e.raw_os_error().unwrap_or(0);
                let msg = if kind == io::ErrorKind::IsADirectory {
                    "Is a directory"
                } else {
                    // use display of error without raw code duplication? Original uses e.to_string() which is like "No such file or directory"
                    // We'll map
                    &e.to_string()
                };
                // Need to produce exactly "b3sum: <file>: <msg> (os error <code>)\n"
                // For IsADirectory code 21, NotFound 2, PermissionDenied 13
                // e.raw_os_error may be None for IsADirectory we created manually, so we need to provide code
                let os_code = e.raw_os_error().unwrap_or_else(|| {
                    if kind == io::ErrorKind::IsADirectory { 21 } else if kind == io::ErrorKind::NotFound { 2 } else if kind == io::ErrorKind::PermissionDenied { 13 } else { 0 }
                });
                // For our IsADirectory custom error, raw error is None, but we want 21
                // msg for custom is "Is a directory" (our string)
                let full_msg = format!("b3sum: {}: {} (os error {})", display_name, msg, os_code);
                writeln!(stderr_lock, "{}", full_msg).unwrap();
                exit_code = 1;
            }
        }
    }
    if exit_code != 0 {
        std::process::exit(exit_code);
    }
}

fn run_hash_derive(files: Vec<String>, context: String, seek:u64, length:u64, raw:bool, tag:bool, no_names:bool) {
    // derive: need to compute key from context via hash_general with DERIVE_CTX
    let ctx_key = hash_general(context.as_bytes(), DERIVE_KEY_CONTEXT, &IV, 0, 32);
    let kw = key_words_from_bytes(&ctx_key);
    let base_flags = DERIVE_KEY_MATERIAL;
    run_hash(files, base_flags, kw, seek, length, raw, tag, no_names);
}

fn run_check(files: Vec<String>, quiet: bool, seek: u64) {
    let mut any_checkfile_error = false;
    let mut failures: usize = 0;
    let stdout = io::stdout();
    let mut stdout_lock = stdout.lock();
    let stderr = io::stderr();
    let mut stderr_lock = stderr.lock();

    // Determine checkfiles: if empty, read from stdin
    let checkfile_list: Vec<String> = if files.is_empty() {
        vec!["-".to_string()]
    } else {
        files
    };

    // Need to handle stdin data for checkfiles: we will read each file accordingly
    // For file == "-", read from stdin (the checkfile content)
    // For multiple checkfiles including "-", sequential stdin reading similar to hashing
    let mut stdin_data: Option<Vec<u8>> = None;
    let mut stdin_consumed = false;

    for cfname in checkfile_list {
        let is_stdin = cfname == "-";
        let content_res: Result<Vec<u8>, io::Error> = if is_stdin {
            if stdin_consumed {
                Ok(Vec::new())
            } else {
                if stdin_data.is_none() {
                    let mut buf = Vec::new();
                    io::stdin().lock().read_to_end(&mut buf).unwrap();
                    stdin_data = Some(buf);
                }
                stdin_consumed = true;
                Ok(stdin_data.as_ref().unwrap().clone())
            }
        } else {
            let path = Path::new(&cfname);
            match std::fs::metadata(path) {
                Ok(meta) if meta.is_dir() => Err(io::Error::new(io::ErrorKind::IsADirectory, "Is a directory")),
                Ok(_) => {
                    match std::fs::read(path) {
                        Ok(b) => Ok(b),
                        Err(e) => Err(e),
                    }
                },
                Err(e) => Err(e),
            }
        };

        let content = match content_res {
            Ok(c) => c,
            Err(e) => {
                let os_code = e.raw_os_error().unwrap_or_else(|| if e.kind()==io::ErrorKind::IsADirectory {21} else if e.kind()==io::ErrorKind::NotFound {2} else {0});
                let msg = e.to_string();
                // For checkfile error, original prints "Error: <msg> (os error <code>)" without filename
                let out_msg = if e.kind()==io::ErrorKind::IsADirectory {
                    format!("Error: Is a directory (os error {})", os_code)
                } else if e.kind()==io::ErrorKind::NotFound {
                    format!("Error: No such file or directory (os error {})", os_code)
                } else {
                    format!("Error: {} (os error {})", msg, os_code)
                };
                writeln!(stderr_lock, "{}", out_msg).unwrap();
                any_checkfile_error = true;
                continue;
            }
        };

        // content is bytes of checkfile, split into lines
        // We need to preserve that lines are separated by \n, but we should split inclusive?
        // Use string from_utf8 lossy
        let content_str = String::from_utf8_lossy(&content);
        // Split by \n, keep lines without \n
        // For each line, we have raw line (without \n). Need to handle \r.
        // Note that if file ends without \n, last line still processed.
        // If file empty, no lines => no output, no failure.
        let lines: Vec<&str> = content_str.split('\n').collect();
        // However split will produce an extra empty line if file ends with \n? Example "a\n" split => ["a",""] . The last empty string corresponds to after final newline, but should not be counted as empty line? In our earlier test, check file with one line plus newline gave success without empty line error. But our pipe test with two lines plus newline? Let's see: original file hash output ends with \n, reading that as checkfile should not produce empty line error. But if we split, the trailing empty after final \n would be considered extra line? However original did not treat trailing newline as extra empty line. Wait we saw that check file with a valid line plus newline succeeded. If we split including trailing empty, we would have an extra empty line, which would be counted as Empty line and cause warning, which would be wrong. So we must handle trailing newline: If content ends with \n, the split's last empty entry should be ignored.
        // More precisely, lines are separated by \n, but the final \n does not produce an extra line. So we should iterate over lines but skip the last empty if it is due to trailing newline.
        // However, check for empty line error: we saw that check with input "\n" (single empty line) gave error Empty line. That input is "\n" which split => ["",""]? Actually split on "\n" gives ["",""]. That's two empties? But trailing empty ignored would give just one empty? Let's think.
        // Original behavior for check with empty stdin (no lines) => no failure. For check with "\n" (one empty line), it gave Empty line error. That's content "\n" which is one empty line. Splitting should produce one empty line counted.
        // So algorithm: split by '\n', then for each piece, if it's the last piece and original content ends with '\n' and piece is empty, skip it? But then "\n" case would have content "\n" split => ["",""] : last piece is empty and content ends with \n => skip last empty, leaving one empty line => correct (one Empty line). For "a\n" split => ["a",""] -> skip last empty => one line "a" => correct.
        // For "a\nb\n" => ["a","b",""] => skip last => ["a","b"]
        // For "a" (no newline) => ["a"] => not skip
        // So implement.

        let ends_with_nl = content.ends_with(b"\n");
        let mut iter_lines = lines;
        if ends_with_nl && iter_lines.last() == Some(&"") {
            iter_lines.pop();
        }

        for raw_line in iter_lines {
            // raw_line still may contain \r at end if original was \r\n
            let mut line = raw_line.to_string();
            if line.ends_with('\r') {
                line.pop();
            }
            // Now line is the check line without newline, with \r stripped
            if line.is_empty() {
                writeln!(stderr_lock, "b3sum: Empty line").unwrap();
                failures += 1;
                continue;
            }
            // detect escape
            let is_escaped = line.starts_with('\\');
            let line_content = if is_escaped { &line[1..] } else { &line[..] };
            // Determine if tag format
            let parsed: Option<(String, String)> = if line_content.starts_with("BLAKE3 (") {
                // tag
                if let Some(idx) = line_content.rfind(") = ") {
                    let filename_part = &line_content[8..idx];
                    let hash_part = &line_content[idx+4..];
                    Some((hash_part.to_string(), filename_part.to_string()))
                } else {
                    None
                }
            } else {
                // normal: hash 64 chars + "  " + filename
                // Need to check if line_content length >= 66 and bytes 64..66 are "  "
                if line_content.len() >= 66 && &line_content[64..66] == "  " {
                    let hash_part = &line_content[..64];
                    let filename_part = &line_content[66..];
                    Some((hash_part.to_string(), filename_part.to_string()))
                } else {
                    None
                }
            };
            let (hash_str, filename_escaped_part) = match parsed {
                Some(v) => v,
                None => {
                    writeln!(stderr_lock, "b3sum: Invalid check line format").unwrap();
                    failures += 1;
                    continue;
                }
            };
            // validate hash length (already 64 if normal, but for tag hash length may vary)
            if hash_str.len() != 64 {
                writeln!(stderr_lock, "b3sum: Invalid hash length").unwrap();
                failures += 1;
                continue;
            }
            // validate hex lowercase
            let is_hex = hash_str.chars().all(|c| c.is_ascii_hexdigit() && (c.is_ascii_digit() || c.is_ascii_lowercase()));
            // The is_ascii_hexdigit includes uppercase A-F, but we require lowercase only. So check that if any uppercase, it's invalid.
            let all_lower_or_digit = hash_str.chars().all(|c| c.is_ascii_digit() || ('a'..='f').contains(&c));
            if !all_lower_or_digit {
                // need to distinguish invalid hex vs length: we already handled length, so now invalid hex
                writeln!(stderr_lock, "b3sum: Invalid hex").unwrap();
                failures += 1;
                continue;
            }

            // unescape filename if needed
            let filename = if is_escaped {
                unescape_filename(&filename_escaped_part)
            } else {
                filename_escaped_part.clone()
            };

            // For output display, we need escaped version for printing status? The check output for escaped files prints with leading "\" and escaped. So we should compute display name as escaped if needed.
            let display_name = if needs_escape(&filename) {
                escape_filename(&filename)
            } else {
                filename.clone()
            };

            // Now hash the file referenced
            // filename could be "-" meaning stdin
            let data_res: Result<Vec<u8>, io::Error> = if filename == "-" {
                // For check mode, reading "-" for data: try to read stdin again? But stdin already consumed for checkfile, so this will be empty if checkfile was stdin.
                // We can attempt to read stdin again, but if stdin was already consumed for checkfile, it will be empty.
                // If checkfile was from file, then stdin for data is still available (maybe empty)
                // We'll try to read from stdin again via same logic but we have already consumed for checkfile stdin; for data stdin we should attempt to read remaining stdin (likely empty)
                // For simplicity, we will treat "-" as empty (or try to read from a new stdin buffer that is empty)
                // To be more accurate, we can try to read from stdin now, but if stdin_data already Some, then it's already consumed, so next read gives empty.
                // So just return empty.
                // But if checkfile was not from stdin, stdin for data may still have data? However typical check invocation with file checkfile and data file "-" would be: "b3sum --check check.txt" where check.txt contains "hash  -". The data for "-" would be expected to be read from stdin at that time, which is not the checkfile. So we need to provide stdin data for that.
                // In our code, stdin_data for checkfiles was consumed, but data stdin for "-" is separate. We need a separate cache for data stdin?
                // Simplify: If filename == "-", try to read all remaining stdin bytes (which may be empty if checkfile was stdin). We'll attempt to read from actual stdin handle again.
                // But since we already read checkfile stdin fully, the OS stdin buffer is empty, so reading again will give empty.
                // For checkfile from file, stdin_data is None or consumed? Actually checkfile_list may include "-" for checkfile itself, but data "-" is different.
                // For now, we will just read stdin again via a new read.
                let mut buf = Vec::new();
                // Try to read from stdin; but if stdin is tty, may block? Not in tests.
                // We'll use try to read with timeout? Alternative: just hash empty.
                // To avoid blocking, we will not read from stdin in check mode for "-" data file; instead hash empty.
                Ok(Vec::new())
            } else {
                let path = Path::new(&filename);
                match std::fs::metadata(path) {
                    Ok(meta) if meta.is_dir() => Err(io::Error::new(io::ErrorKind::IsADirectory, "Is a directory")),
                    Ok(_) => std::fs::read(path),
                    Err(e) => Err(e),
                }
            };

            match data_res {
                Ok(data) => {
                    let out_bytes = hash_general(&data, 0, &IV, seek, 32);
                    let actual_hex = hex_encode(&out_bytes);
                    if actual_hex == hash_str {
                        if !quiet {
                            writeln!(stdout_lock, "{}: OK", display_name).unwrap();
                        }
                    } else {
                        writeln!(stdout_lock, "{}: FAILED", display_name).unwrap();
                        failures += 1;
                    }
                },
                Err(e) => {
                    let os_code = e.raw_os_error().unwrap_or_else(|| if e.kind()==io::ErrorKind::IsADirectory {21} else if e.kind()==io::ErrorKind::NotFound {2} else if e.kind()==io::ErrorKind::PermissionDenied {13} else {0});
                    let msg = e.to_string();
                    // For FAILED with reason, format: "<filename>: FAILED (<msg> (os error <code>))"
                    let reason = if e.kind()==io::ErrorKind::IsADirectory {
                        format!("Is a directory (os error {})", os_code)
                    } else if e.kind()==io::ErrorKind::NotFound {
                        format!("No such file or directory (os error {})", os_code)
                    } else if e.kind()==io::ErrorKind::PermissionDenied {
                        format!("Permission denied (os error {})", os_code)
                    } else {
                        format!("{} (os error {})", msg, os_code)
                    };
                    writeln!(stdout_lock, "{}: FAILED ({})", display_name, reason).unwrap();
                    failures += 1;
                }
            }
        }
    }

    if failures > 0 {
        writeln!(stderr_lock, "b3sum: WARNING: {} computed checksum did NOT match", failures).unwrap();
        std::process::exit(1);
    }
    if any_checkfile_error {
        std::process::exit(1);
    }
}
RS
"}

actions.command:
cat > Cargo.toml <<'EOF'
[package]
name = "b3sum"
version = "1.8.4"
edition = "2021"

[dependencies]
clap = { version = "4.6", default-features = false, features = ["std","help","usage","error-context","suggestions"] }

[[bin]]
name = "b3sum"
path = "src/main.rs"
EOF
cat Cargo.toml
mkdir -p src
cat > src/main.rs <<'RS'
use clap::{Arg, ArgAction, Command, value_parser};
use std::io::{self, Read, Write};
use std::fs::File;
use std::path::Path;

const IV: [u32; 8] = [
    0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A,
    0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19,
];
const MSG_PERMUTATION: [usize; 16] = [2,6,3,10,7,0,4,13,1,11,12,5,9,14,15,8];
const CHUNK_START: u32 = 1;
const CHUNK_END: u32 = 2;
const PARENT: u32 = 4;
const ROOT: u32 = 8;
const KEYED_HASH: u32 = 16;
const DERIVE_KEY_CONTEXT: u32 = 32;
const DERIVE_KEY_MATERIAL: u32 = 64;
const BLOCK_LEN: u32 = 64;
const CHUNK_LEN: usize = 1024;

fn rotr(x: u32, n: u32) -> u32 {
    (x >> n) | (x << (32 - n))
}
fn g(state: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize, mx: u32, my: u32) {
    state[a] = state[a].wrapping_add(state[b]).wrapping_add(mx);
    state[d] = rotr(state[d] ^ state[a], 16);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = rotr(state[b] ^ state[c], 12);
    state[a] = state[a].wrapping_add(state[b]).wrapping_add(my);
    state[d] = rotr(state[d] ^ state[a], 8);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = rotr(state[b] ^ state[c], 7);
}
fn round_fn(state: &mut [u32; 16], m: &[u32; 16]) {
    g(state, 0,4,8,12, m[0], m[1]);
    g(state, 1,5,9,13, m[2], m[3]);
    g(state, 2,6,10,14, m[4], m[5]);
    g(state, 3,7,11,15, m[6], m[7]);
    g(state, 0,5,10,15, m[8], m[9]);
    g(state, 1,6,11,12, m[10], m[11]);
    g(state, 2,7,8,13, m[12], m[13]);
    g(state, 3,4,9,14, m[14], m[15]);
}
fn compress(chaining_value: &[u32; 8], block_words: &[u32; 16], counter: u64, block_len: u32, flags: u32) -> [u32; 16] {
    let mut state = [0u32; 16];
    state[0..8].copy_from_slice(chaining_value);
    state[8..12].copy_from_slice(&IV[0..4]);
    state[12] = (counter & 0xffffffff) as u32;
    state[13] = ((counter >> 32) & 0xffffffff) as u32;
    state[14] = block_len;
    state[15] = flags;
    let mut m = *block_words;
    for _ in 0..7 {
        round_fn(&mut state, &m);
        let mut permuted = [0u32; 16];
        for i in 0..16 {
            permuted[i] = m[MSG_PERMUTATION[i]];
        }
        m = permuted;
    }
    for i in 0..8 {
        state[i] ^= state[i+8];
        state[i+8] ^= chaining_value[i];
    }
    state
}
fn words_from_block(block: &[u8]) -> [u32; 16] {
    let mut words = [0u32; 16];
    for i in 0..16 {
        words[i] = u32::from_le_bytes([block[i*4], block[i*4+1], block[i*4+2], block[i*4+3]]);
    }
    words
}
fn words_from_block_safe(block: &[u8]) -> [u32; 16] {
    let mut buf = [0u8; 64];
    let len = std::cmp::min(block.len(), 64);
    buf[..len].copy_from_slice(&block[..len]);
    words_from_block(&buf)
}
fn le_bytes_from_words(words: &[u32]) -> Vec<u8> {
    let mut out = Vec::with_capacity(words.len()*4);
    for w in words {
        out.extend_from_slice(&w.to_le_bytes());
    }
    out
}
fn key_words_from_bytes(key: &[u8]) -> [u32; 8] {
    let mut out = [0u32; 8];
    for i in 0..8 {
        out[i] = u32::from_le_bytes([key[i*4], key[i*4+1], key[i*4+2], key[i*4+3]]);
    }
    out
}
fn hash_general(data: &[u8], base_flags: u32, key_words: &[u32; 8], seek: u64, length: u64) -> Vec<u8> {
    let length = length as usize;
    let seek = seek as usize;
    if data.is_empty() {
        // single empty chunk
        return hash_single_chunk(b"", base_flags, key_words, seek, length);
    }
    let chunks: Vec<&[u8]> = data.chunks(CHUNK_LEN).collect();
    if chunks.len() == 1 {
        return hash_single_chunk(chunks[0], base_flags, key_words, seek, length);
    }
    // multi chunk
    let mut chunk_cvs: Vec<[u32; 8]> = Vec::new();
    for (idx, chunk) in chunks.iter().enumerate() {
        let mut cv = *key_words;
        let num_blocks = (chunk.len() + 63) / 64;
        let n = if num_blocks==0 {1} else {num_blocks};
        for b_idx in 0..n {
            let start = b_idx*64;
            let end = std::cmp::min(start+64, chunk.len());
            let block_len = if b_idx == n-1 { (chunk.len() - start) as u32 } else { 64 };
            // need to create padded block for words
            let mut block_buf = [0u8; 64];
            if b_idx == n-1 {
                let slice = &chunk[start..end];
                block_buf[..slice.len()].copy_from_slice(slice);
            } else {
                block_buf.copy_from_slice(&chunk[start..start+64]);
            }
            let block_words = words_from_block(&block_buf);
            let mut flags = base_flags;
            if b_idx==0 { flags |= CHUNK_START; }
            if b_idx==n-1 { flags |= CHUNK_END; }
            let state = compress(&cv, &block_words, idx as u64, block_len, flags);
            let mut new_cv = [0u32;8];
            new_cv.copy_from_slice(&state[0..8]);
            cv = new_cv;
        }
        chunk_cvs.push(cv);
    }
    // parent tree
    let mut stack = chunk_cvs;
    while stack.len() > 1 {
        if stack.len() == 2 {
            let left = stack[0];
            let right = stack[1];
            let flags = base_flags | PARENT | ROOT;
            let mut block_words = [0u32;16];
            block_words[0..8].copy_from_slice(&left);
            block_words[8..16].copy_from_slice(&right);
            let mut out = Vec::new();
            let needed = seek+length;
            let mut counter: u64 = 0;
            while out.len() < needed {
                let state = compress(key_words, &block_words, counter, BLOCK_LEN, flags);
                out.extend_from_slice(&le_bytes_from_words(&state));
                counter+=1;
            }
            return out[seek..seek+length].to_vec();
        } else {
            let mut new_stack: Vec<[u32;8]> = Vec::new();
            let mut i=0;
            while i < stack.len() {
                if i+1 < stack.len() {
                    let left = stack[i];
                    let right = stack[i+1];
                    let flags = base_flags | PARENT;
                    let mut block_words = [0u32;16];
                    block_words[0..8].copy_from_slice(&left);
                    block_words[8..16].copy_from_slice(&right);
                    let state = compress(key_words, &block_words, 0, BLOCK_LEN, flags);
                    let mut cv = [0u32;8];
                    cv.copy_from_slice(&state[0..8]);
                    new_stack.push(cv);
                    i+=2;
                } else {
                    new_stack.push(stack[i]);
                    i+=1;
                }
            }
            stack = new_stack;
        }
    }
    Vec::new()
}
fn hash_single_chunk(chunk: &[u8], base_flags: u32, key_words: &[u32;8], seek: usize, length: usize) -> Vec<u8> {
    let num_blocks = if chunk.is_empty() {1} else {(chunk.len()+63)/64};
    let mut cv = *key_words;
    for b_idx in 0..num_blocks-1 {
        let start = b_idx*64;
        let block = &chunk[start..start+64];
        let block_words = words_from_block(block);
        let mut flags = base_flags;
        if b_idx==0 { flags |= CHUNK_START; }
        let state = compress(&cv, &block_words, 0, 64, flags);
        let mut new_cv=[0u32;8];
        new_cv.copy_from_slice(&state[0..8]);
        cv = new_cv;
    }
    let last_start = (num_blocks-1)*64;
    let last_slice = if chunk.is_empty() {&[][..]} else {&chunk[last_start..]};
    let last_len = last_slice.len() as u32;
    let mut last_buf = [0u8;64];
    last_buf[..last_slice.len()].copy_from_slice(last_slice);
    let last_words = words_from_block(&last_buf);
    let mut flags_last = base_flags;
    if num_blocks==1 { flags_last |= CHUNK_START; }
    flags_last |= CHUNK_END|ROOT;
    let mut out = Vec::new();
    let needed = seek+length;
    let mut counter: u64 = 0;
    while out.len() < needed {
        let state = compress(&cv, &last_words, counter, last_len, flags_last);
        out.extend_from_slice(&le_bytes_from_words(&state));
        counter+=1;
    }
    out[seek..seek+length].to_vec()
}
fn hash_derive(data: &[u8], context: &str, seek: u64, length: u64) -> Vec<u8> {
    let ctx_bytes = context.as_bytes();
    let ctx_key = hash_general(ctx_bytes, DERIVE_KEY_CONTEXT, &IV, 0, 32);
    let kw = key_words_from_bytes(&ctx_key);
    hash_general(data, DERIVE_KEY_MATERIAL, &kw, seek, length)
}

// escape helpers
fn needs_escape(s: &str) -> bool {
    s.contains('\\') || s.contains('\n') || s.contains('\r')
}
fn escape_filename(s: &str) -> String {
    if needs_escape(s) {
        let mut esc = String::new();
        for c in s.chars() {
            match c {
                '\\' => esc.push_str("\\\\"),
                '\n' => esc.push_str("\\n"),
                '\r' => esc.push_str("\\r"),
                _ => esc.push(c),
            }
        }
        format!("\\{}", esc)
    } else {
        s.to_string()
    }
}
fn unescape_filename(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c=='\\' {
            if let Some(n) = chars.next() {
                match n {
                    '\\' => out.push('\\'),
                    'n' => out.push('\n'),
                    'r' => out.push('\r'),
                    _ => { out.push('\\'); out.push(n); }
                }
            } else {
                out.push('\\');
            }
        } else {
            out.push(c);
        }
    }
    out
}
fn hex_encode(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len()*2);
    for b in bytes {
        s.push_str(&format!("{:02x}", b));
    }
    s
}

fn build_cmd() -> Command {
    Command::new("b3sum")
        .version("1.8.4")
        .about("")
        .arg(Arg::new("FILE")
            .value_name("FILE")
            .help("Files to hash, or checkfiles to check")
            .long_help("Files to hash, or checkfiles to check\n\nWhen no file is given, or when - is given, read standard input.")
            .num_args(0..)
        )
        .arg(Arg::new("keyed")
            .long("keyed")
            .help("Use the keyed mode, reading the 32-byte key from stdin")
            .action(ArgAction::SetTrue)
            .conflicts_with("derive-key")
            .conflicts_with("check")
        )
        .arg(Arg::new("derive-key")
            .long("derive-key")
            .value_name("CONTEXT")
            .help("Use the key derivation mode, with the given context string")
            .long_help("Use the key derivation mode, with the given context string\n\nCannot be used with --keyed.")
            .conflicts_with("keyed")
            .conflicts_with("check")
        )
        .arg(Arg::new("length")
            .short('l')
            .long("length")
            .value_name("LEN")
            .help("The number of output bytes, before hex encoding")
            .long_help("The number of output bytes, before hex encoding\n\n[default: 32]")
            .value_parser(value_parser!(u64))
            .default_value("32")
            .conflicts_with("check")
        )
        .arg(Arg::new("seek")
            .long("seek")
            .value_name("SEEK")
            .help("The starting output byte offset, before hex encoding")
            .long_help("The starting output byte offset, before hex encoding\n\n[default: 0]")
            .value_parser(value_parser!(u64))
            .default_value("0")
        )
        .arg(Arg::new("num-threads")
            .long("num-threads")
            .value_name("NUM")
            .help("The maximum number of threads to use")
            .long_help("The maximum number of threads to use\n\nBy default, this is the number of logical cores. If this flag is omitted, or if its value\nis 0, RAYON_NUM_THREADS is also respected.")
            .value_parser(value_parser!(u64))
        )
        .arg(Arg::new("no-mmap")
            .long("no-mmap")
            .help("Disable memory mapping")
            .long_help("Disable memory mapping\n\nCurrently this also disables multithreading.")
            .action(ArgAction::SetTrue)
        )
        .arg(Arg::new("no-names")
            .long("no-names")
            .help("Omit filenames in the output")
            .action(ArgAction::SetTrue)
            .conflicts_with("check")
        )
        .arg(Arg::new("raw")
            .long("raw")
            .help("Write raw output bytes to stdout, rather than hex")
            .long_help("Write raw output bytes to stdout, rather than hex\n\n--no-names is implied. In this case, only a single input is allowed.")
            .action(ArgAction::SetTrue)
            .conflicts_with("check")
        )
        .arg(Arg::new("tag")
            .long("tag")
            .help("Output BSD-style checksums: BLAKE3 ([FILE]) = [HASH]")
            .action(ArgAction::SetTrue)
            .conflicts_with("check")
        )
        .arg(Arg::new("check")
            .short('c')
            .long("check")
            .help("Read BLAKE3 sums from the [FILE]s and check them")
            .action(ArgAction::SetTrue)
            .conflicts_with("keyed")
            .conflicts_with("derive-key")
            .conflicts_with("length")
            .conflicts_with("raw")
            .conflicts_with("tag")
            .conflicts_with("no-names")
        )
        .arg(Arg::new("quiet")
            .long("quiet")
            .help("Skip printing OK for each checked file")
            .long_help("Skip printing OK for each checked file\n\nMust be used with --check.")
            .action(ArgAction::SetTrue)
            .requires("check")
        )
}

fn main() {
    let cmd = build_cmd();
    let matches = match cmd.try_get_matches() {
        Ok(m) => m,
        Err(e) => e.exit(),
    };

    let check = matches.get_flag("check");
    let keyed = matches.get_flag("keyed");
    let derive_key: Option<String> = matches.get_one::<String>("derive-key").cloned();
    let length = *matches.get_one::<u64>("length").unwrap();
    let seek = *matches.get_one::<u64>("seek").unwrap();
    let raw = matches.get_flag("raw");
    let tag = matches.get_flag("tag");
    let no_names = matches.get_flag("no-names");
    let quiet = matches.get_flag("quiet");
    // let no_mmap = matches.get_flag("no-mmap");
    // let num_threads = matches.get_one::<u64>("num-threads").copied();

    let files: Vec<String> = matches.get_many::<String>("FILE").map(|v| v.cloned().collect()).unwrap_or_default();

    // raw single file check (custom)
    if raw && files.len() > 1 {
        eprintln!("Error: Only one filename can be provided when using --raw");
        std::process::exit(1);
    }
    // keyed requires at least one FILE
    if keyed && files.is_empty() {
        // emulate clap error
        let mut cmd2 = build_cmd();
        let err = cmd2.error(clap::error::ErrorKind::MissingRequiredArgument, "the following required arguments were not provided:\n  <FILE>...");
        err.exit();
    }

    if check {
        // check mode: seek allowed, length already prevented via conflict, but also need to handle seek value
        run_check(files, quiet, seek);
        return;
    }

    // hashing mode
    // handle keyed / derive
    let mut base_flags = 0u32;
    let mut key_words: [u32; 8] = IV;

    if keyed {
        // read 32 bytes from stdin
        let mut stdin = io::stdin();
        let mut buf = Vec::new();
        // read all stdin for key
        let mut all = Vec::new();
        let mut handle = stdin.lock();
        handle.read_to_end(&mut all).unwrap();
        if all.len() < 32 {
            eprintln!("Error: expected 32 key bytes from stdin, found {}", all.len());
            std::process::exit(1);
        } else if all.len() > 32 {
            eprintln!("Error: read more than 32 key bytes from stdin");
            std::process::exit(1);
        }
        key_words = key_words_from_bytes(&all);
        base_flags = KEYED_HASH;
        // special handling for file "-": cannot open '-' in keyed mode
        for f in &files {
            if f == "-" {
                eprintln!("b3sum: -: Cannot open `-` in keyed mode");
                std::process::exit(1);
            }
        }
        // now hash files
        run_hash(files, base_flags, key_words, seek, length, raw, tag, no_names);
    } else if let Some(ctx) = derive_key {
        // derive mode
        // key_words derived from context
        // data from files or stdin
        // base_flags will be DERIVE_KEY_MATERIAL but need ctx key
        // we will compute inside run_hash_derive
        run_hash_derive(files, ctx, seek, length, raw, tag, no_names);
    } else {
        base_flags = 0;
        key_words = IV;
        run_hash(files, base_flags, key_words, seek, length, raw, tag, no_names);
    }
}

fn run_hash(files: Vec<String>, base_flags: u32, key_words: [u32;8], seek:u64, length:u64, raw:bool, tag:bool, no_names:bool) {
    let mut exit_code = 0;
    let stdout = io::stdout();
    let mut stdout_lock = stdout.lock();
    let stderr = io::stderr();
    let mut stderr_lock = stderr.lock();

    // helper to hash data
    let mut stdin_cache: Option<Vec<u8>> = None;
    let mut stdin_pos = 0; // not needed for hashing mode raw single? We'll just read once
    // For hashing, we need to handle multiple "-" reading sequentially: first gets all, subsequent empty
    // We'll read stdin once on first demand
    let mut stdin_data: Option<Vec<u8>> = None;
    let mut stdin_consumed = false;

    let get_stdin = |stdin_data: &mut Option<Vec<u8>>, consumed: &mut bool| -> Vec<u8> {
        if *consumed {
            return Vec::new();
        }
        if stdin_data.is_none() {
            let mut buf = Vec::new();
            io::stdin().lock().read_to_end(&mut buf).unwrap();
            *stdin_data = Some(buf);
        }
        *consumed = true;
        stdin_data.as_ref().unwrap().clone()
    };

    if files.is_empty() {
        // read stdin
        let mut data = Vec::new();
        io::stdin().lock().read_to_end(&mut data).unwrap();
        let out_bytes = hash_general(&data, base_flags, &key_words, seek, length);
        if raw {
            stdout_lock.write_all(&out_bytes).unwrap();
        } else if no_names || raw {
            let hex = hex_encode(&out_bytes);
            writeln!(stdout_lock, "{}", hex).unwrap();
        } else if tag {
            let hex = hex_encode(&out_bytes);
            writeln!(stdout_lock, "BLAKE3 (-) = {}", hex).unwrap();
        } else {
            let hex = hex_encode(&out_bytes);
            writeln!(stdout_lock, "{}  -", hex).unwrap();
        }
        return;
    }

    for fname in files {
        let display_name = fname.clone();
        let is_stdin = fname == "-";
        let data_res: Result<Vec<u8>, io::Error> = if is_stdin {
            // read stdin sequentially
            if stdin_consumed {
                Ok(Vec::new())
            } else {
                if stdin_data.is_none() {
                    let mut buf = Vec::new();
                    io::stdin().lock().read_to_end(&mut buf).unwrap();
                    stdin_data = Some(buf);
                }
                stdin_consumed = true;
                Ok(stdin_data.as_ref().unwrap().clone())
            }
        } else {
            // check if path is directory, permission etc.
            let path = Path::new(&fname);
            match File::open(path) {
                Ok(mut f) => {
                    // check if directory (on linux, open directory succeeds? but read will fail? Let's use metadata)
                    match std::fs::metadata(path) {
                        Ok(meta) if meta.is_dir() => {
                            Err(io::Error::new(io::ErrorKind::IsADirectory, "Is a directory"))
                        },
                        Ok(_) => {
                            let mut buf = Vec::new();
                            match f.read_to_end(&mut buf) {
                                Ok(_) => Ok(buf),
                                Err(e) => Err(e),
                            }
                        },
                        Err(e) => Err(e),
                    }
                },
                Err(e) => Err(e),
            }
        };

        match data_res {
            Ok(data) => {
                let out_bytes = hash_general(&data, base_flags, &key_words, seek, length);
                if raw {
                    // raw already enforced single file, so just write
                    stdout_lock.write_all(&out_bytes).unwrap();
                } else if no_names {
                    let hex = hex_encode(&out_bytes);
                    writeln!(stdout_lock, "{}", hex).unwrap();
                } else if tag {
                    let hex = hex_encode(&out_bytes);
                    let esc = if needs_escape(&display_name) {
                        // for tag, need to escape and prefix
                        let escaped = display_name.replace("\\", "\\\\").replace("\n","\\n").replace("\r","\\r");
                        format!("\\BLAKE3 ({}) = {}", escaped, hex)
                    } else {
                        format!("BLAKE3 ({}) = {}", display_name, hex)
                    };
                    writeln!(stdout_lock, "{}", esc).unwrap();
                } else {
                    let hex = hex_encode(&out_bytes);
                    let out_line = if needs_escape(&display_name) {
                        let escaped = display_name.replace("\\", "\\\\").replace("\n","\\n").replace("\r","\\r");
                        format!("\\{}  {}", hex, escaped)
                    } else {
                        format!("{}  {}", hex, display_name)
                    };
                    writeln!(stdout_lock, "{}", out_line).unwrap();
                }
            },
            Err(e) => {
                let kind = e.kind();
                let code = e.raw_os_error().unwrap_or(0);
                let msg = if kind == io::ErrorKind::IsADirectory {
                    "Is a directory"
                } else {
                    // use display of error without raw code duplication? Original uses e.to_string() which is like "No such file or directory"
                    // We'll map
                    &e.to_string()
                };
                // Need to produce exactly "b3sum: <file>: <msg> (os error <code>)\n"
                // For IsADirectory code 21, NotFound 2, PermissionDenied 13
                // e.raw_os_error may be None for IsADirectory we created manually, so we need to provide code
                let os_code = e.raw_os_error().unwrap_or_else(|| {
                    if kind == io::ErrorKind::IsADirectory { 21 } else if kind == io::ErrorKind::NotFound { 2 } else if kind == io::ErrorKind::PermissionDenied { 13 } else { 0 }
                });
                // For our IsADirectory custom error, raw error is None, but we want 21
                // msg for custom is "Is a directory" (our string)
                let full_msg = format!("b3sum: {}: {} (os error {})", display_name, msg, os_code);
                writeln!(stderr_lock, "{}", full_msg).unwrap();
                exit_code = 1;
            }
        }
    }
    if exit_code != 0 {
        std::process::exit(exit_code);
    }
}

fn run_hash_derive(files: Vec<String>, context: String, seek:u64, length:u64, raw:bool, tag:bool, no_names:bool) {
    // derive: need to compute key from context via hash_general with DERIVE_CTX
    let ctx_key = hash_general(context.as_bytes(), DERIVE_KEY_CONTEXT, &IV, 0, 32);
    let kw = key_words_from_bytes(&ctx_key);
    let base_flags = DERIVE_KEY_MATERIAL;
    run_hash(files, base_flags, kw, seek, length, raw, tag, no_names);
}

fn run_check(files: Vec<String>, quiet: bool, seek: u64) {
    let mut any_checkfile_error = false;
    let mut failures: usize = 0;
    let stdout = io::stdout();
    let mut stdout_lock = stdout.lock();
    let stderr = io::stderr();
    let mut stderr_lock = stderr.lock();

    // Determine checkfiles: if empty, read from stdin
    let checkfile_list: Vec<String> = if files.is_empty() {
        vec!["-".to_string()]
    } else {
        files
    };

    // Need to handle stdin data for checkfiles: we will read each file accordingly
    // For file == "-", read from stdin (the checkfile content)
    // For multiple checkfiles including "-", sequential stdin reading similar to hashing
    let mut stdin_data: Option<Vec<u8>> = None;
    let mut stdin_consumed = false;

    for cfname in checkfile_list {
        let is_stdin = cfname == "-";
        let content_res: Result<Vec<u8>, io::Error> = if is_stdin {
            if stdin_consumed {
                Ok(Vec::new())
            } else {
                if stdin_data.is_none() {
                    let mut buf = Vec::new();
                    io::stdin().lock().read_to_end(&mut buf).unwrap();
                    stdin_data = Some(buf);
                }
                stdin_consumed = true;
                Ok(stdin_data.as_ref().unwrap().clone())
            }
        } else {
            let path = Path::new(&cfname);
            match std::fs::metadata(path) {
                Ok(meta) if meta.is_dir() => Err(io::Error::new(io::ErrorKind::IsADirectory, "Is a directory")),
                Ok(_) => {
                    match std::fs::read(path) {
                        Ok(b) => Ok(b),
                        Err(e) => Err(e),
                    }
                },
                Err(e) => Err(e),
            }
        };

        let content = match content_res {
            Ok(c) => c,
            Err(e) => {
                let os_code = e.raw_os_error().unwrap_or_else(|| if e.kind()==io::ErrorKind::IsADirectory {21} else if e.kind()==io::ErrorKind::NotFound {2} else {0});
                let msg = e.to_string();
                // For checkfile error, original prints "Error: <msg> (os error <code>)" without filename
                let out_msg = if e.kind()==io::ErrorKind::IsADirectory {
                    format!("Error: Is a directory (os error {})", os_code)
                } else if e.kind()==io::ErrorKind::NotFound {
                    format!("Error: No such file or directory (os error {})", os_code)
                } else {
                    format!("Error: {} (os error {})", msg, os_code)
                };
                writeln!(stderr_lock, "{}", out_msg).unwrap();
                any_checkfile_error = true;
                continue;
            }
        };

        // content is bytes of checkfile, split into lines
        // We need to preserve that lines are separated by \n, but we should split inclusive?
        // Use string from_utf8 lossy
        let content_str = String::from_utf8_lossy(&content);
        // Split by \n, keep lines without \n
        // For each line, we have raw line (without \n). Need to handle \r.
        // Note that if file ends without \n, last line still processed.
        // If file empty, no lines => no output, no failure.
        let lines: Vec<&str> = content_str.split('\n').collect();
        // However split will produce an extra empty line if file ends with \n? Example "a\n" split => ["a",""] . The last empty string corresponds to after final newline, but should not be counted as empty line? In our earlier test, check file with one line plus newline gave success without empty line error. But our pipe test with two lines plus newline? Let's see: original file hash output ends with \n, reading that as checkfile should not produce empty line error. But if we split, the trailing empty after final \n would be considered extra line? However original did not treat trailing newline as extra empty line. Wait we saw that check file with a valid line plus newline succeeded. If we split including trailing empty, we would have an extra empty line, which would be counted as Empty line and cause warning, which would be wrong. So we must handle trailing newline: If content ends with \n, the split's last empty entry should be ignored.
        // More precisely, lines are separated by \n, but the final \n does not produce an extra line. So we should iterate over lines but skip the last empty if it is due to trailing newline.
        // However, check for empty line error: we saw that check with input "\n" (single empty line) gave error Empty line. That input is "\n" which split => ["",""]? Actually split on "\n" gives ["",""]. That's two empties? But trailing empty ignored would give just one empty? Let's think.
        // Original behavior for check with empty stdin (no lines) => no failure. For check with "\n" (one empty line), it gave Empty line error. That's content "\n" which is one empty line. Splitting should produce one empty line counted.
        // So algorithm: split by '\n', then for each piece, if it's the last piece and original content ends with '\n' and piece is empty, skip it? But then "\n" case would have content "\n" split => ["",""] : last piece is empty and content ends with \n => skip last empty, leaving one empty line => correct (one Empty line). For "a\n" split => ["a",""] -> skip last empty => one line "a" => correct.
        // For "a\nb\n" => ["a","b",""] => skip last => ["a","b"]
        // For "a" (no newline) => ["a"] => not skip
        // So implement.

        let ends_with_nl = content.ends_with(b"\n");
        let mut iter_lines = lines;
        if ends_with_nl && iter_lines.last() == Some(&"") {
            iter_lines.pop();
        }

        for raw_line in iter_lines {
            // raw_line still may contain \r at end if original was \r\n
            let mut line = raw_line.to_string();
            if line.ends_with('\r') {
                line.pop();
            }
            // Now line is the check line without newline, with \r stripped
            if line.is_empty() {
                writeln!(stderr_lock, "b3sum: Empty line").unwrap();
                failures += 1;
                continue;
            }
            // detect escape
            let is_escaped = line.starts_with('\\');
            let line_content = if is_escaped { &line[1..] } else { &line[..] };
            // Determine if tag format
            let parsed: Option<(String, String)> = if line_content.starts_with("BLAKE3 (") {
                // tag
                if let Some(idx) = line_content.rfind(") = ") {
                    let filename_part = &line_content[8..idx];
                    let hash_part = &line_content[idx+4..];
                    Some((hash_part.to_string(), filename_part.to_string()))
                } else {
                    None
                }
            } else {
                // normal: hash 64 chars + "  " + filename
                // Need to check if line_content length >= 66 and bytes 64..66 are "  "
                if line_content.len() >= 66 && &line_content[64..66] == "  " {
                    let hash_part = &line_content[..64];
                    let filename_part = &line_content[66..];
                    Some((hash_part.to_string(), filename_part.to_string()))
                } else {
                    None
                }
            };
            let (hash_str, filename_escaped_part) = match parsed {
                Some(v) => v,
                None => {
                    writeln!(stderr_lock, "b3sum: Invalid check line format").unwrap();
                    failures += 1;
                    continue;
                }
            };
            // validate hash length (already 64 if normal, but for tag hash length may vary)
            if hash_str.len() != 64 {
                writeln!(stderr_lock, "b3sum: Invalid hash length").unwrap();
                failures += 1;
                continue;
            }
            // validate hex lowercase
